changeSet.sql:
create or alter procedure [graph].[UpdateAssetNode] @uid uniqueidentifier, @updatePath bit = 0 as begin declare @id bigint, @typeId bigint; select @id = id, @typeId = assetTypeId from Asset where [uid] = @uid;
if exists (select 1 from graph.AssetNode where [uid] = @uid) and not exists (select 1 from Asset where [uid] = @uid) begin -- Delete any edge relationships connected to this asset. delete E from graph.AssetEdge E inner join graph.AssetNode N on E.$from_id = N.$node_id where N.[uid] = @uid
delete E from graph.AssetEdge E inner join graph.AssetNode N on E.$to_id = N.$node_id where N.[uid] = @uid
-- Delete rule results where the asset we are deleting is the owner of the results (i.e. a Rule). drop table if exists #Uids create table #Uids (Uid uniqueidentifier) create clustered index CIX_TempUids on #Uids (Uid)
-- Get all Result Uids where the asset is the result owner. insert into #Uids select R.Uid from graph.AssetNode A, dbo.AssetResultEdge E, dbo.AssetResult R where MATCH(A-(E)->R) and E.Class = 1 and A.Uid = @uid;
--Delete all edge records including those linking the result to the evaluated asset. delete E from dbo.AssetResultEdge E inner join AssetResult AR on E.$to_id = AR.$node_id inner join #Uids S on S.Uid = AR.Uid
--Delete all remaining edge records linked to the Asset, e.g. Where asset is not owner. delete E from dbo.AssetResultEdge E inner join graph.AssetNode N on E.$from_id = N.$node_id where N.[uid] = @uid;
delete T from dbo.AssetResult T inner join #Uids S on S.Uid = T.Uid;
delete from graph.AssetNode where [uid] = @uid; end else if exists (select 1 from graph.AssetNode where [uid] = @uid) begin update N set N.UpdatedOn = A.UpdatedOn, N.[State] = A.[State], N.AssetTypeID = A.AssetTypeID, N.AssetTypeUid = T.[Uid], N.Class = T.Class from graph.AssetNode N inner join Asset A on A.ID = N.ID inner join AssetType T on T.ID = A.AssetTypeId where A.[uid] = @uid;
if @updatePath = 1 begin exec graph.UpdateGraphTableHierarchyBy null, null, @id end end else begin insert into graph.AssetNode (ID, [Uid], AssetTypeID, AssetTypeUid, [State], UpdatedOn, Class) select A.ID, A.Uid, A.AssetTypeID, T.[Uid] as AssetTypeUid, A.[State], A.UpdatedOn, T.Class from Asset A inner join AssetType T on T.ID = A.AssetTypeID where A.[uid] = @uid;
exec graph.UpdateGraphTableHierarchyBy null, null, @id end end

changeSet.rollback:
